<include file="Publics:header"/>	<div class="mainbox">		<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('Library/index_nav_pop',$_GET)}" class="on">首页自定义导航列表</a>|                <if condition="$assign_type['type_14']"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Library/nav_add_pop')}','添加广告',850,580,true,false,false,addbtn,'add',true);">添加广告</a> </if>			</ul>		</div>		<div class="page_tips">图标建议尺寸：图片宽度建议为：586px，高度建议为：734px。<span style="color:red;">当配置多个活动同时生效时，系统取最新配置(ID最大)的那个活动展示给用户</span></div>		<form name="myform" id="myform" action="{pigcms{:U('Library/index_nav_pop')}" method="get">            <div>		    <input type="hidden" name="g" value="House"/>            <input type="hidden" name="c" value="Library"/>            <input type="hidden" name="a" value="index_nav_pop"/>            <input type="hidden" name="frame_show" value="true"/>            <input type="hidden" name="frame" value="1"/>            弹窗名称：<input value="{pigcms{$_GET['key_name']}" class="col-sm-2" name="key_name" id="key_name" type="text" style="float: none;height:35px;margin:10px;width: 180px;"/>            状态：<select name="status" id="status" class="col-sm-1" style="float: none;height:35px;margin:10px;width: 100px;">                        <option value="0" <if condition="$_GET['status'] eq 0">selected="selected"</if>>全部</option>						<option value="1" <if condition="$_GET['status'] eq 1">selected="selected"</if>>关闭</option>                        <option value="2" <if condition="$_GET['status'] eq 2">selected="selected"</if>>正常</option>					</select>             活动时间：<input type="text" name="start_time" id="start_time" autocomplete="off" class="col-sm-1" value="{pigcms{$_GET['start_time']}"  style="float: none;height:35px;margin:10px;width: 120px;" onfocus="WdatePicker({isShowClear:false,readOnly:false,dateFmt:'yyyy-MM-dd'})" placeholder="开始日期" /> —            <input type="text" name="end_time"  id="end_time" autocomplete="off" class="col-sm-1" value="{pigcms{$_GET['end_time']}"  style="float: none;height:35px;margin:10px;width: 120px;" onfocus="WdatePicker({isShowClear:false,readOnly:false,dateFmt:'yyyy-MM-dd'})" placeholder="结束日期"/>&nbsp;&nbsp;&nbsp;&nbsp;            <input style="line-height: 10px;" class="btn btn-success" type="submit" id="find_submit" value=" 搜 索 " />            <a style="line-height: 10px;margin-left: 20px;"  class="btn btn-success" href="{pigcms{:U('Library/index_nav_pop',array('frame_show'=>true,'frame'=>1))}" >重置</a>            <span class="form_tips"></span>         </div>			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>ID</th>							<th>弹窗名称</th>							<th>活动时间</th>							<th>状态</th>                            <if condition="$assign_type['type_14']"><th class="textcenter">操作</th></if>						</tr>					</thead>					<tbody>						<if condition="is_array($result['list']) AND !empty($result['list'])">							<volist name="result['list']" id="vo">								<tr>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.start_time_str} 至 {pigcms{$vo.end_time_str}</td>									<td>									<if condition="$vo['status'] eq 1">										<font color="green">正常</font>									<elseif condition="$vo['status'] eq 0"/>										<font color="red">关闭</font>									</if></td>                                    <if condition="$assign_type['type_14']">									<td class="textcenter">                                       <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Library/nav_add_pop',array('id'=>$vo['id']))}','编辑广告信息',850,580,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Library/nav_del_pop')}">删除</a>                                    </td>                                    </if>								</tr>							</volist>						<else/>							<tr>                                <td class="textcenter red"  <if condition="$assign_type['type_14']"> colspan="5" <else/>colspan="4"</if>>列表为空！</td>                            </tr>						</if>					</tbody>				</table>                {pigcms{$result.pagebar}			</div>		</form>	</div><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }</style><include file="Publics:footer"/>